node - digest <<'NODE'
const fs=require('node:fs'),c=require('node:crypto');
const b=JSON.parse(fs.readFileSync('docs/remediation/design/W22.07/baseline.json','utf8')),hash=bytes=>c.createHash('sha256').update(bytes).digest('hex'),pin=x=>({path:x.path,sha256:hash(fs.readFileSync(x.path))}),owned=new Set(b.owned_before.map(x=>x.path));
const expected=[...b.protected,...b.accepted_dependencies.flatMap(d=>[...d.files.filter(x=>!owned.has(x.path)),d.review])];
const protectedMismatches=expected.filter(x=>pin(x).sha256!==x.sha256).map(x=>x.path);
const map=[...new Map([...b.owned_before,...expected].map(x=>[x.path,pin(x)])).values()].sort((a,b)=>a.path.localeCompare(b.path));
console.log(JSON.stringify({at:new Date().toISOString(),pin_count:map.length,pin_digest:hash(JSON.stringify(map)),protected_mismatches:protectedMismatches,...(process.argv[2]==='full'?{pins:map}:{}),owned:b.owned_before.map(pin)}));
if(protectedMismatches.length)process.exitCode=1;
NODE

