node --max-old-space-size=512 --input-type=module <<'NODE'
import fs from 'node:fs'; import z from 'node:zlib'; import { ESLint } from 'eslint';
const b=JSON.parse(fs.readFileSync('docs/remediation/design/W22.07/baseline.json','utf8'));
const files=b.owned_before.filter(x=>x.path.endsWith('.ts')), results=await new ESLint().lintFiles(files.map(x=>x.path));
const rows=results.map(r=>({path:r.filePath.split('/__cloudflare_base/')[1],errors:r.errorCount,warnings:r.warningCount,signatures:r.messages.map(m=>[m.ruleId,m.message]).sort()}));
const differences=[], newWarningSource=[];
for(const row of rows) {
 const previous=b.lint.rows.find(p=>p.path===row.path)?.signatures??[], remaining=previous.map(x=>JSON.stringify(x));
 for(const signature of row.signatures){const key=JSON.stringify(signature),i=remaining.indexOf(key);if(i<0)differences.push({path:row.path,signature});else remaining.splice(i,1);}
 const original=files.find(p=>p.path===row.path), originalLines=new Set((original.gzip_base64?z.gunzipSync(Buffer.from(original.gzip_base64,'base64')).toString():'').split('\n').map(x=>x.trim()));
 const source=fs.readFileSync(row.path,'utf8').split('\n');
 for(const m of results.find(r=>r.filePath.endsWith('/'+row.path)).messages)if(!originalLines.has((source[m.line-1]??'').trim()))newWarningSource.push({path:row.path,line:m.line,rule:m.ruleId,message:m.message,source:source[m.line-1]});
}
const helper=fs.readFileSync('src/reflex/bufferedAction.ts','utf8').split('\n'), helperWhitespace=helper.flatMap((line,i)=>/[\t ]+$/.test(line)?[i+1]:[]);
const errors=rows.reduce((n,r)=>n+r.errors,0), warnings=rows.reduce((n,r)=>n+r.warnings,0);
console.log(JSON.stringify({errors,warnings,baseline_errors:b.lint.errors,baseline_warnings:b.lint.warnings,rows,new_signatures:differences,new_warning_source:newWarningSource,new_helper_trailing_whitespace:helperWhitespace}));
process.exitCode=errors||warnings>b.lint.warnings||differences.length||newWarningSource.length||helperWhitespace.length?1:0;
NODE
